const setReturnStatus = `-- name: SetReturnStatus :execrows
UPDATE returns SET
    status          = $1,
    approved_at     = CASE WHEN $1::text = 'APPROVED'  THEN now() ELSE approved_at END,
    rejected_at     = CASE WHEN $1::text = 'REJECTED'  THEN now() ELSE rejected_at END,
    completed_at    = CASE WHEN $1::text = 'COMPLETED' THEN now() ELSE completed_at END,
    resolution_note = CASE WHEN $2::text <> '' THEN $2::text ELSE resolution_note END
WHERE id = $3 AND status = $4
`

type SetReturnStatusParams struct {
	ToStatus   string
	Note       string
	ID         int64
	FromStatus string
}

// SetReturnStatus moves a return from one status to the next; 0 rows when
// the return is no longer in the expected status.
func (q *Queries) SetReturnStatus(ctx context.Context, arg SetReturnStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setReturnStatus,
		arg.ToStatus,
		arg.Note,
		arg.ID,
		arg.FromStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
